"""Printed 269–272: given elements, translation and intersection opening."""
import math
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path
def graph(n):
 vertical=n==31;h=1;k=-2 if n==32 else 1;a=12 if n==32 else 2;b=5 if n==32 else 1.4;c=math.sqrt(a*a+b*b);s=11 if n==32 else 50
 def pt(x,y):return(260+s*(x-h),200-s*(y-k))
 paths=[path([pt(h-20 if n==32 else h-4,0),pt(h+20 if n==32 else h+4,0)]),path([pt(0,k-9 if n==32 else k-3.3),pt(0,k+10 if n==32 else k+3.3)])]
 for sign in [-1,1]:
  pts=[]
  for i in range(-100,101,2):t=i/100;x=sign*a*math.cosh(t);y=b*math.sinh(t);pts.append(pt(h+y,k+x) if vertical else pt(h+x,k+y))
  paths.append(path(pts))
 m=a/b if vertical else b/a;span=18 if n==32 else 2
 for sign in [-1,1]:paths.append(path([pt(h-span,k+sign*m*-span),pt(h+span,k+sign*m*span)],dash=True))
 points=[(h,k)];labels=[(268,223,'C(1,−2)' if n==32 else 'C(h,k)'),(481,pt(h,0)[1]+7,'x'),(pt(0,k)[0],22,'y')]
 for value,kind in [(a,'V'),(c,'F')]:
  for sign in [-1,1]:x,y=(h,k+sign*value) if vertical else (h+sign*value,k);points.append((x,y));xx,yy=pt(x,y)
  if n==32:
   for sign in [-1,1]:x=h+sign*value;xx,yy=pt(x,k);labels.append((xx-55 if sign<0 else xx+5,yy+23 if kind=='V' else yy-10,f'{kind}({x:g},−2)'))
  else:
   for sign in [-1,1]:x,y=(h,k+sign*value) if vertical else (h+sign*value,k);xx,yy=pt(x,y);labels.append((xx+7,yy-9,f'{kind}(h,k'+('+' if sign>0 else '−')+('a)' if kind=='V' else 'c)') if vertical else f'{kind}(h'+('+' if sign>0 else '−')+('a,k)' if kind=='V' else 'c,k)')))
 if n==32:
  paths.append(path([pt(h-a,k-b),pt(h+a,k-b),pt(h+a,k+b),pt(h-a,k+b),pt(h-a,k-b)],dash=True));labels.extend([(287,136,'12y−5x+29=0'),(285,289,'12y+5x+19=0')])
 return geometry('Figure 9.'+str(n),'Figure 9.'+str(n)+' — translated '+('vertical' if vertical else 'horizontal')+' hyperbola with vertices, foci and asymptotes',paths,labels,points=[{'x':pt(x,y)[0],'y':pt(x,y)[1]} for x,y in points],size=(550,400))
PAGES=[page('139_page_1.jpg',269,[heading('(iv) Equation of hyperbola through its elements'),heading('Example 21'),paragraph('Find vertices, foci, eccentricity and asymptotes of 16x²−9y²=144.'),heading('Solution'),eq(r'16x^2-9y^2=144\quad\Rightarrow\quad\frac{16x^2}{144}-\frac{9y^2}{144}=1\quad\Rightarrow\quad\frac{x^2}{9}-\frac{y^2}{16}=1'),paragraph('If the transverse axis is the x-axis, select a²=9,a=3 and b²=16,b=4. Find c:'),eq(r'c=\sqrt{a^2+b^2}=\sqrt{9+16}=\pm5'),paragraph('The vertices, foci, eccentricity and asymptotes are:'),eq(r'V_1(a,0)=V_1(3,0),\quad V_2(-a,0)=V_2(-3,0)'),eq(r'F_1(c,0)=F_1(5,0),\quad F_2(-c,0)=F_2(-5,0)'),eq(r'e=\frac c a=\frac53>1'),eq(r'y=\pm\frac b a x=\pm\frac43x'),heading('Example 22'),paragraph('Find the hyperbola when one focus is (0,6), center C(0,0), eccentricity 3.'),heading('Solution'),paragraph('Focus (0,6) gives c=6 and transverse axis the y-axis. Eccentricity 3 gives a:'),eq(r'e=\frac c a\quad\Rightarrow\quad3=\frac6a\quad\Rightarrow\quad a=2'),paragraph('Use a and c to find b:'),eq(r'c^2=a^2+b^2\quad\Rightarrow\quad b^2=c^2-a^2=36-4=32'),eq(r'\frac{y^2}{a^2}-\frac{x^2}{b^2}=1\quad\Rightarrow\quad\frac{y^2}{4}-\frac{x^2}{32}=1,\quad a^2=4,\ b^2=32'),heading('(v) Standard form of equation of Hyperbola'),paragraph('Select any point (h,k) as center and a major axis parallel to x- or y-axis. With the geometrical definition, a new set of hyperbola equations can be derived through translation of axes.'),heading('Translation of hyperbola horizontally'),paragraph('For center C(h,k), vertices V₁(h+a,k),V₂(h−a,k), foci F₁(h−c,k),F₂(h+c,k), the standard form is:'),eq(r'\frac{(x-h)^2}{a^2}-\frac{(y-k)^2}{b^2}=1','72'),note('The focal distance c is the positive square root; ±5 refers to the two focal coordinates in Example 21. Hyperbola uses a transverse axis rather than an ellipse’s major axis.')]),
page('139_page_2.jpg',270,[graph(30),heading('Translation of hyperbola vertically'),paragraph('For center C(h,k), vertices V₁(h,k+a),V₂(h,k−a), foci F₁(h,k+c),F₂(h,k−c), the standard form is:'),eq(r'\frac{(y-k)^2}{a^2}-\frac{(x-h)^2}{b^2}=1','73'),graph(31),paragraph('Orientation with center C(h,k) is summarized:'),{'type':'dataTable','headers':['Orientation','Foci','Vertices'],'rows':[['Horizontal','F₁(h−c,k),F₂(h+c,k)','V₁(h−a,k),V₂(h+a,k)'],['Vertical','F₁(h,k+c),F₂(h,k−c)','V₁(h,k+a),V₂(h,k−a)']]},eq(r'c^2=a^2+b^2,\quad c>0'),heading('Example 23'),paragraph('Sketch (x−1)²/144−(y+2)²/25=1, with center C(h,k) and transverse axis the x-axis. Determine vertices and foci.'),heading('Solution'),paragraph('The given hyperbola is continued on printed 271.'),note('In Example 23 the transverse axis is parallel to the x-axis through y=−2, not the x-axis y=0 itself. Native Figures 9.30–9.31 use an illustrative shifted center while retaining symbolic h,k labels.')]),
page('140_page_1.jpg',271,[eq(r'\frac{(x-1)^2}{144}-\frac{(y+2)^2}{25}=1','74'),paragraph('Substitute X=x−h=x−1,Y=y−k=y+2,h=1,k=−2 to obtain the new hyperbola in the XY system:'),eq(r'\frac{X^2}{144}-\frac{Y^2}{25}=1','75'),paragraph('Hyperbola (75) has transverse axis on the x-axis, giving a²=144,a=12 and b²=25,b=5. Find c:'),eq(r'c=\sqrt{a^2+b^2}=\sqrt{144+25}=13'),paragraph('Coordinates of vertices and foci in the XY system:'),eq(r'V_1(-a,0)=V_1(-12,0),\quad V_2(a,0)=V_2(12,0)'),eq(r'F_1(-c,0)=F_1(-13,0),\quad F_2(c,0)=F_2(13,0)'),paragraph('Asymptotes in the XY system:'),eq(r'Y=\frac b a X=\frac5{12}X,\quad Y=-\frac b a X=-\frac5{12}X'),paragraph('Coordinates in the original xy system:'),eq(r'V_1(h+a,k)=V_1(13,-2),\quad V_2(h-a,k)=V_2(-11,-2)'),eq(r'F_1(h-c,k)=F_1(-12,-2),\quad F_2(h+c,k)=V_2(14,-2)'),paragraph('Convert the asymptotes from XY to xy:'),eq(r'Y=\frac b a X=\frac5{12}X,\quad a=12,\ b=5'),eq(r'y-k=\frac5{12}(x-h),\quad h=1,\ k=-2'),eq(r'y+2=\frac5{12}(x-1)\quad\Rightarrow\quad12y+24=5x-5\quad\Rightarrow\quad12y-5x+29=0'),eq(r'Y=-\frac b a X=-\frac5{12}X'),eq(r'y-k=-\frac5{12}(x-h)\quad\Rightarrow\quad y+2=-\frac5{12}(x-1)\quad\Rightarrow\quad12y+24=-5x+5\quad\Rightarrow\quad12y+5x+19=0'),paragraph('Having sketched asymptotes and vertices, sketch the hyperbola as in Figure 9.32.'),note('The source accidentally labels F₂(h+c,k) as V₂(14,−2); the point is the focus F₂(14,−2). It also changes V₁/V₂ numbering across the XY and xy lists; the unordered vertex and focus pairs remain correct. Exact center is (1,−2), vertices (−11,−2),(13,−2), foci (−12,−2),(14,−2).')]),
page('140_page_2.jpg',272,[graph(32),paragraph('For the horizontally translated hyperbola (x−h)²/a²−(y−k)²/b²=1, asymptotes are:'),eq(r'y-k=\pm\frac b a(x-h)','76'),paragraph('For vertically translated (y−k)²/a²−(x−h)²/b²=1, asymptotes are:'),eq(r'y-k=\pm\frac a b(x-h)','77'),heading('(vi) Recognition of tangent and normal to hyperbola'),paragraph('A line which intersects a hyperbola in two coincident points is a tangent. For the hyperbola, there will be two tangents [real and distinct, coincident (with an asymptote), or complex] with a given slope. The formulation for tangents will be discussed in succeeding sections.'),heading('(vii) Point of intersection of hyperbola with a line including the condition of tangency'),paragraph('The given line and hyperbola:'),eq(r'y=mx+c','78'),eq(r'\frac{x^2}{a^2}-\frac{y^2}{b^2}=1','79'),paragraph('develop a system of nonlinear equations:'),eq(r'\frac{x^2}{a^2}-\frac{y^2}{b^2}=1,\quad y=mx+c','80'),paragraph('The solution set exists if the curves intersect; find the intersection points by solving system (80) simultaneously. Use line (78) in hyperbola (79):'),eq(r'\frac{x^2}{a^2}-\frac{(mx+c)^2}{b^2}=1'),eq(r'x^2(b^2-a^2m^2)-2a^2mcx+a^2(c^2+b^2)=0','81'),note('The final constant sign in source equation (81) is wrong. Correct expansion: (b²−a²m²)x²−2a²mcx−a²(c²+b²)=0. If b²−a²m²=0, this is linear rather than quadratic unless it is the asymptote through the center, which has no finite intersection. A line of an asymptote slope cannot be a finite-contact tangent; treating coincident asymptotes as tangents is a limiting statement. For the horizontal hyperbola, finite-slope real tangents require |m|>b/a. Vertical tangents x=h±a remain valid and must be handled separately.')])]
for v in PAGES:v.update(title='CONICS-II',visualStatus='Complete source translations, exact native figures and intersection equation with separate sign correction',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':(v['page']+9)//2,'side':'left' if v['page']%2 else 'right','reason':'All source signs, shifted coordinates, focal labels and asymptote coefficients visually checked'})
EXAMPLES=[]
for n,q,steps,ans,start,end in [
('21','Find vertices, foci, eccentricity and asymptotes of 16x²−9y²=144.',['Divide by 144 to obtain x²/9−y²/16=1.','The transverse axis is horizontal; a=3,b=4 and center (0,0).','Vertices are (±3,0). Compute c=√(9+16)=5.','The foci are (±5,0), and eccentricity e=c/a=5/3>1.','Asymptotes are y=±(b/a)x=±4x/3.','Check c²−a²=25−9=16=b², and each vertex satisfies the original equation 16·9=144.'],'V(±3,0), F(±5,0), e=5/3, y=±4x/3.',269,269),
('22','Find the hyperbola with focus (0,6), center (0,0), eccentricity 3.',['The center-focus direction is vertical, so the transverse axis is y and c=6.','Use e=c/a=3 to obtain a=2.','Compute b²=c²−a²=36−4=32.','Use vertical standard form y²/a²−x²/b²=1.','Thus y²/4−x²/32=1, vertices (0,±2), foci (0,±6).','The recovered focal distance is √(4+32)=6 and eccentricity is 6/2=3, verifying the source data.'],'y²/4−x²/32=1.',269,269),
('23','Sketch (x−1)²/144−(y+2)²/25=1 and find vertices and foci.',['Read center (h,k)=(1,−2), with horizontal transverse axis.','The semiaxes are a=12,b=5; c=√(144+25)=13.','Vertices (h±a,k) are (−11,−2),(13,−2).','Foci (h±c,k) are (−12,−2),(14,−2).','Asymptotes: y+2=±(5/12)(x−1), or 12y−5x+29=0 and 12y+5x+19=0.','Draw the construction rectangle centered (1,−2), corners (1±12,−2±5), its diagonals, then the two branches through the vertices.','Substituting either vertex gives 1; both asymptotes pass through the center. The source’s V₂ label at (14,−2) is a focus-label typo.'],'C(1,−2), V(−11,−2),(13,−2), F(−12,−2),(14,−2); asymptotes y+2=±5(x−1)/12.',270,272)]:
 e={'num':n,'title':'Hyperbola Elements and Translation','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'jpg':f'{(pg+9)//2:03d}_page_{1 if pg%2 else 2}.jpg','verification':'Complete source question, signs and translated geometry checked'} for pg in range(start,end+1)]}
 if n=='23':e['sourceQuestionBlocks']=[graph(32)]
 EXAMPLES.append(e)
